    "__kernel void hashx_pow(__global const uint4 *prog, uint code_size, ulong k0,\n"
    ""
    "                        ulong k1, ulong k2, ulong k3, uint difficulty,\n"
    ""
    "                        uint base, uint count, __global hx_results *res) {\n"
    ""
    "    uint idx = get_global_id(0);\n"
    ""
    "    ulong r[8];\n"
    ""
    "    ulong v0, v1, v2, v3;\n"
    ""
    "    int target = 0;\n"
    ""
    "    int be = 1;\n"
    ""
    "    uint result = 0;\n"
    ""
    "    int i;\n"
    ""
    "    ulong w[4];\n"
    ""
    "    uchar dg[32];\n"
    ""
    "    int ok = 1;\n"
    ""
    "    uint nonce;\n"
    ""
    "\n"
    ""
    "    if (idx >= count) {\n"
    ""
    "        return;\n"
    ""
    "    }\n"
    ""
    "    nonce = base + idx;\n"
    ""
    "    v0 = k0;\n"
    ""
    "    v1 = k1;\n"
    ""
    "    v2 = k2;\n"
    ""
    "    v3 = k3;\n"
    ""
    "    v1 ^= 0xeeUL;\n"
    ""
    "    v3 ^= (ulong)nonce;\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    v0 ^= (ulong)nonce;\n"
    ""
    "    v2 ^= 0xeeUL;\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    r[0] = v0;\n"
    ""
    "    r[1] = v1;\n"
    ""
    "    r[2] = v2;\n"
    ""
    "    r[3] = v3;\n"
    ""
    "    v1 ^= 0xddUL;\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    r[4] = v0;\n"
    ""
    "    r[5] = v1;\n"
    ""
    "    r[6] = v2;\n"
    ""
    "    r[7] = v3;\n"
    ""
    "\n"
    ""
    "    i = 0;\n"
    ""
    "    while (i < (int)code_size) {\n"
    ""
    "        uint4 in = prog[i];\n"
    ""
    "        uint op = in.x;\n"
    ""
    "        uint dst = in.y;\n"
    ""
    "        uint src = in.z;\n"
    ""
    "        uint imm = in.w;\n"
    ""
    "        switch (op) {\n"
    ""
    "        case 0: /* UMULH_R */\n"
    ""
    "            r[dst] = mul_hi(r[dst], r[src]);\n"
    ""
    "            result = (uint)r[dst];\n"
    ""
    "            break;\n"
    ""
    "        case 1: /* SMULH_R */\n"
    ""
    "            r[dst] = (ulong)mul_hi((long)r[dst], (long)r[src]);\n"
    ""
    "            result = (uint)r[dst];\n"
    ""
    "            break;\n"
    ""
    "        case 2: r[dst] *= r[src]; break;\n"
    ""
    "        case 3: r[dst] -= r[src]; break;\n"
    ""
    "        case 4: r[dst] ^= r[src]; break;\n"
    ""
    "        case 5: r[dst] += r[src] << (imm & 63u); break;\n"
    ""
    "        case 6: r[dst] = rotr64(r[dst], (int)(imm & 63u)); break;\n"
    ""
    "        case 7: r[dst] += (ulong)(long)(int)imm; break;\n"
    ""
    "        case 8: r[dst] ^= (ulong)(long)(int)imm; break;\n"
    ""
    "        case 9: target = i; break;\n"
    ""
    "        case 10:\n"
    ""
    "            if (be && (result & imm) == 0u) {\n"
    ""
    "                i = target;\n"
    ""
    "                be = 0;\n"
    ""
    "            }\n"
    ""
    "            break;\n"
    ""
    "        default: break;\n"
    ""
    "        }\n"
    ""
    "        i++;\n"
    ""
    "    }\n"
    ""
    "\n"
    ""
    "    r[0] += k0;\n"
    ""
    "    r[1] += k1;\n"
    ""
    "    r[6] += k2;\n"
    ""
    "    r[7] += k3;\n"
    ""
    "    v0 = r[0];\n"
    ""
    "    v1 = r[1];\n"
    ""
    "    v2 = r[2];\n"
    ""
    "    v3 = r[3];\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    r[0] = v0;\n"
    ""
    "    r[1] = v1;\n"
    ""
    "    r[2] = v2;\n"
    ""
    "    r[3] = v3;\n"
    ""
    "    v0 = r[4];\n"
    ""
    "    v1 = r[5];\n"
    ""
    "    v2 = r[6];\n"
    ""
    "    v3 = r[7];\n"
    ""
    "    SIPROUND(v0, v1, v2, v3);\n"
    ""
    "    r[4] = v0;\n"
    ""
    "    r[5] = v1;\n"
    ""
    "    r[6] = v2;\n"
    ""
    "    r[7] = v3;\n"
    ""
    "    w[0] = r[0] ^ r[4];\n"
    ""
    "    w[1] = r[1] ^ r[5];\n"
    ""
    "    w[2] = r[2] ^ r[6];\n"
    ""
    "    w[3] = r[3] ^ r[7];\n"
    ""
    "    for (i = 0; i < 4; i++) {\n"
    ""
    "        for (int j = 0; j < 8; j++) {\n"
    ""
    "            dg[8 * i + j] = (uchar)(w[i] >> (8 * j));\n"
    ""
    "        }\n"
    ""
    "    }\n"
    ""
    "    for (uint b = 0; b < difficulty; b++) {\n"
    ""
    "        if (((dg[b >> 3] >> (7u - (b & 7u))) & 1u) != 0u) {\n"
    ""
    "            ok = 0;\n"
    ""
    "            break;\n"
    ""
    "        }\n"
    ""
    "    }\n"
    ""
    "    if (ok) {\n"
    ""
    "        uint slot = atomic_inc(&res->count);\n"
    ""
    "        if (slot < 8u) {\n"
    ""
    "            res->nonces[slot] = nonce;\n"
    ""
    "            for (i = 0; i < 8; i++) {\n"
    ""
    "                res->hashes[slot][i] = ((uint)dg[4 * i] << 24) |\n"
    ""
    "                                       ((uint)dg[4 * i + 1] << 16) |\n"
    ""
    "                                       ((uint)dg[4 * i + 2] << 8) |\n"
    ""
    "                                       (uint)dg[4 * i + 3];\n"
    ""
    "            }\n"
    ""
    "        }\n"
    ""
    "    }\n"
    ""
    "}\n"
    ""
;
